import React, { useState } from "react";
import { useLocation } from "react-router-dom";
import "./QueryScreen.css";
import { FaPaperPlane } from "react-icons/fa"; // Import send icon

function QueryScreen() {
  const location = useLocation();
  const { response } = location.state || {};
  const [message, setMessage] = useState("");

  const handleSend = async () => {
    console.log("Message sent:", message);
    // setLoading(true); // Set loading to true when form is submitted
    const formData = {
      age: { age },
      coverage_amt: { coverage },
      tobacco: { tobacco },
      occupation: { occupation },
      prompt: message,
    };

    try {
      const response = await axios.post("http://localhost:5000/res", formData, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(response.data)
      setLoading(false); // Set loading to false when response is received
      navigate("/query", { state: { response: response.data, age, coverage, tobacco, occupation } });
    } catch (error) {
      setLoading(false); // Set loading to false if there is an error
      console.error("Error submitting the form", error);
    }
    setMessage("");
  };

  return (
    <div className="query-screen">
      <div className="message-box">
        <div className="recommendations">
          {response ? (
            <div dangerouslySetInnerHTML={{ __html: response.response }} />
          ) : (
            <p>No recommendations available.</p>
          )}
        </div>
        <div className="input-box">
          <input
            type="text"
            placeholder="Ask me something"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
          />
          <button onClick={handleSend}>
            <FaPaperPlane />
          </button>
        </div>
      </div>
    </div>
  );
}

export default QueryScreen;
